function UnifySDKHelper:Analysis_Register()
    local data = RegisterData()
    data.account = PlayerDataManager:Get():GetPlayerUID() or UnifySDKManager:Get():ISDK():GetDeviceId()
    data.customParam = self:Analysis_GetCustomData(PlayerDataManager:Get():GetPlayerRID())
    --UnifySDKManager:Get():IAnalysis():Register(data)
    UnifySDKEventSystem:Publish(data);
end

function UnifySDKHelper:Analysis_Login()
    local data = LoginData()
    data.account = PlayerDataManager:Get():GetPlayerUID()
    data.serverId = PlayerDataManager:Get():GetPlayerServerID()
    data.customParam = self:Analysis_GetCustomData(PlayerDataManager:Get():GetPlayerRID())
    --UnifySDKManager:Get():IAnalysis():Login(data)
    UnifySDKEventSystem:Publish(data);
end

function UnifySDKHelper:Analysis_Order(orderID, currencyType, currencyAmount)
    local data = OrderData()
    data.orderID = orderID
    data.currencyType = currencyType
    data.currencyAmount = currencyAmount
    data.customParam = self:Analysis_GetCustomData(PlayerDataManager:Get():GetPlayerRID())
    --UnifySDKManager:Get():IAnalysis():Order(data)
    UnifySDKEventSystem:Publish(data);
end

function UnifySDKHelper:Analysis_GetCustomData(Rid)
    local data = {}
    data.Rid = Rid
    return Dll_JSON.encode(data)
end

